using Microsoft.Win32;using SasControls;using SasDataLib;using SasDefine;using SasFormBrowes;using System;using System.Collections.Generic;using System.Data;using System.IO;using System.Windows;using System.Windows.Input;using System.Linq;using System.Data.SqlClient;using System.Net.Mail;using System.Windows.Documents;using System.Windows.Media;using System.Windows.Controls;using System.Xml.Linq;using System.Net.Mime;using System.Text;using System.Net;namespace CrmDmEmailcr{    public partial class FrmSendEmaiCr : FormList    {        private DataTable newDataTable = new DataTable();        private DataTable OldRow = (DataTable)null;        private EditModeBindingObject FormInEditMode;        public FrmSendEmaiCr()        {            this.InitializeComponent();            this.BindingSasObj = StartupBase.SasObj;            this.DisplayLanguage = StartupBase.M_LAN;            SysFunc.LoadIcon((Window)this);            this.FormInEditMode = (EditModeBindingObject)this.FindResource("IsInEditMode");        }        private void LoadForm()        {            DataTable sqlTableFieldList = ListFunc.GetSqlTableFieldList(StartupBase.SasObj, "CRMailMessagePH");

            this.txtemail_from.MaxLength = ListFunc.GetLengthColumn(sqlTableFieldList, "email_from");
            this.txttieu_de.MaxLength = ListFunc.GetLengthColumn(sqlTableFieldList, "tieu_de");            this.txtemail_to_list.MaxLength = ListFunc.GetLengthColumn(sqlTableFieldList, "email_to_list");            this.txtma_kh_list.MaxLength = ListFunc.GetLengthColumn(sqlTableFieldList, "ma_kh_list");            this.Title = "Gui Email";            this.txtemail_from.Text = Info.fromAddress.ToString().Trim();            this.txttieu_de.Text = Info.subject.ToString().Trim();            this.Smtp = CreateSmtp(Info.fromAddress, Info.fromPass, "smtp.gmail.com", 587);            this.dtPH = new DataTable();            this.dtPH.Columns.Add("messageid", typeof(string));            this.dtPH.Columns.Add("email_from", typeof(string));            this.dtPH.Columns.Add("tieu_de", typeof(string));            this.dtPH.Columns.Add("noi_dung", typeof(string));            this.dtPH.Columns.Add("noi_dung_html", typeof(string));            this.dtPH.Columns.Add("ma_kh_list", typeof(string));            this.dtPH.Columns.Add("email_to_list", typeof(string));            this.dtPH.Columns.Add("machinename", typeof(string));            this.dtPH.Columns.Add("machineuser", typeof(string));            this.dtPH.Columns.Add("user_name", typeof(string));            this.dtPH.Columns.Add("user_id", typeof(Int32));            this.dtPH.Columns.Add("datesent", typeof(DateTime));            this.dtPH.Columns.Add("timesent", typeof(string));            this.dtCT = new DataTable();            this.dtCT.Columns.Add("messageid", typeof(string));            this.dtCT.Columns.Add("stt", typeof(Int32));            this.dtCT.Columns.Add("filename", typeof(string));            this.dtCT.Columns.Add("file_contain", typeof(byte[]));        }        private static SmtpClient CreateSmtp(string fromAddress, string fromPassword, string host, int port)        {            return new SmtpClient()            {                Host = host,                Port = port,                EnableSsl = true,                DeliveryMethod = SmtpDeliveryMethod.Network,                UseDefaultCredentials = false,                Credentials = (ICredentialsByHost)new NetworkCredential(fromAddress, fromPassword)            };        }        private void newForm_Loaded(object sender, RoutedEventArgs e)        {            this.LoadForm();        }               public void EnableEditMode(bool isEditMode)        {            this.FormInEditMode.IsEditMode = isEditMode;        }        private void FormList_Closed(object sender, EventArgs e)        {            StartUp.currActionTask = ActionTask.None;        }        private void FormList_PreviewKeyUp(object sender, KeyEventArgs e)        {            if (Keyboard.Modifiers != ModifierKeys.None || e.Key != Key.Escape)                return;            StartUp.LastEditTable = (DataTable)null;            this.Close();        }        private void btnfile_Click(object sender, RoutedEventArgs e)        {            string currentDirectory = Environment.CurrentDirectory;            double num1 = Convert.ToDouble(StartupBase.SasObj.GetSysvar("M_FILE_ATTACH_SIZE").ToString());            string str1 = string.Join("|", ((IEnumerable<string>)StartupBase.SasObj.GetSysvar("M_FILE_ATTACH_TYPE").ToString().Split(',')).Select<string, string>((Func<string, string>)(x => x.ToString() + "(*." + x.ToString() + ")|*." + x.ToString().Trim())).ToArray<string>());            string str2 = "";            OpenFileDialog openFileDialog = new OpenFileDialog();            openFileDialog.Multiselect = true;            openFileDialog.FileName = str2;            openFileDialog.Filter = "File đính kèm" + str1 + "|All (*.*)|*.*";            bool? nullable = openFileDialog.ShowDialog();            if ((!nullable.GetValueOrDefault() ? 0 : (nullable.HasValue ? 1 : 0)) != 0)            {                this.lbFiles.Items.Clear();                this.lbFiles.UpdateLayout();                double sizeSfile = 0;                foreach (string filename in openFileDialog.FileNames)                {                    double sizefile = (double)new FileInfo(filename).Length;                    sizeSfile += sizefile;                    if (sizeSfile > (5 * 1048576.0))                    {                        this.lbFiles.Items.Clear();                        this.lbFiles.UpdateLayout();                        int num2 = (int)ExMessageBox.Show(15, StartupBase.SasObj, "Kích thước file vượt quá 5M!", "", MessageBoxButton.OK, MessageBoxImage.Asterisk);                        this.lbFiles.Focus();                        break;                    }                    else                    {                        this.lbFiles.Items.Add(Path.GetFullPath(filename).ToString().Trim());                    }                }            }            Environment.CurrentDirectory = currentDirectory;        }        private void CreateTableEmail(MailMessage newmsg)        {            string _messageid = Guid.NewGuid().ToString().Trim();            DataRow rowph = this.dtPH.NewRow();            rowph["messageid"] = _messageid;            rowph["email_from"] = this.txtemail_from.Text.Trim();            rowph["tieu_de"] = this.txttieu_de.Text.Trim();            rowph["noi_dung"] = this.strText.ToString().Trim();            rowph["noi_dung_html"] = this.strHtml.ToString().Trim();            rowph["ma_kh_list"] = this.txtma_kh_list.Text.Trim();            rowph["email_to_list"] = this.txtemail_to_list.Text.Trim();            rowph["machinename"] = Environment.MachineName;            rowph["machineuser"] = Environment.UserName;            rowph["user_name"] = StartupBase.SasObj.UserInfo.Rows[0]["user_name"].ToString().Trim();            rowph["user_id"] = Convert.ToInt32(StartupBase.SasObj.UserInfo.Rows[0]["user_id"].ToString().Trim());            rowph["datesent"] = DateTime.Now.Date;            rowph["timesent"] = DateTime.Now.ToString("HH:mm:ss");            this.dtPH.Rows.Add(rowph);            if (this.lbFiles.Items != null && this.lbFiles.Items.Count > 0)            {                int count = this.lbFiles.Items.Count;                for (int i = 0; i < count; i++)                {                    string file = this.lbFiles.Items[i].ToString().Trim();                    DataRow rowct = this.dtCT.NewRow();                    rowct["messageid"] = _messageid;                    rowct["stt"] = i + 1;                    rowct["filename"] = Path.GetFileName(file);                    rowct["file_contain"] = File.ReadAllBytes(file);                    this.dtCT.Rows.Add(rowct);                }            }        }        string strHtml = "";        string strText = "";        private void btnSend_Click(object sender, RoutedEventArgs e)        {            strHtml = this.Editor.ContentHtml == null? "": this.Editor.ContentHtml.ToString();            strText = this.Editor.ContentText == null? "": this.Editor.ContentText.ToString();            Info.subject = this.txttieu_de.Text.Trim();            Info.toAddress = this.txtemail_to_list.Text;            if (!this.CheckValid())                return;            this.sent_mail();        }        private void btnCancel_Click(object sender, RoutedEventArgs e)        {            this.Close();        }        private SmtpClient Smtp;        private FrmWaiting wait;        private DataTable dtPH;        private DataTable dtCT;        private bool CheckValid()        {            if (strHtml.Trim() == string.Empty)            {                int num = (int)ExMessageBox.Show(20, StartupBase.SasObj, "Chưa vào nội dung góp ý!", "", MessageBoxButton.OK, MessageBoxImage.Asterisk);                this.Editor.Focus();                return false;            }            if (this.lbFiles.Items != null && this.lbFiles.Items.Count > 0)            {                bool flag = true;                int count = this.lbFiles.Items.Count;                for (int i = 0; i < count; i++)                {                    if (!System.IO.File.Exists(this.lbFiles.Items[i].ToString().Trim()))                    {                        int num = (int)ExMessageBox.Show(21, StartupBase.SasObj, string.Format("Tập tin [{0}] không tồn tại!", this.lbFiles.Items[i].ToString().Trim()), "", MessageBoxButton.OK, MessageBoxImage.Asterisk);                        flag = false;                        break;                    }                }                if (!flag)                {                    this.lbFiles.Focus();                    return flag;                }            }            if (string.IsNullOrEmpty(this.txttieu_de.Text.Trim()))            {                int num = (int)ExMessageBox.Show(12, StartupBase.SasObj, "Tiêu đề không được phép trống!", "", MessageBoxButton.OK, MessageBoxImage.Asterisk);                this.txttieu_de.Focus();                return false;            }            if (string.IsNullOrEmpty(this.txtemail_from.Text.Trim()))            {                int num = (int)ExMessageBox.Show(13, StartupBase.SasObj, "Email không được bỏ trống!", "", MessageBoxButton.OK, MessageBoxImage.Asterisk);                this.txtemail_from.Focus();                return false;            }            if (string.IsNullOrEmpty(this.txtemail_to_list.Text.Trim()))            {                int num = (int)ExMessageBox.Show(13, StartupBase.SasObj, "Danh sách Email nhận không được bỏ trống!", "", MessageBoxButton.OK, MessageBoxImage.Asterisk);                this.txtemail_to_list.Focus();                return false;            }            try            {                MailAddress mailAddress = new MailAddress(this.txtemail_from.Text);            }            catch            {                int num = (int)ExMessageBox.Show(40, StartupBase.SasObj, "Email không hợp lệ!", "", MessageBoxButton.OK, MessageBoxImage.Asterisk);                this.txtemail_from.Focus();                return false;            }            return true;        }        private void sent_mail()        {            this.wait = new FrmWaiting(600.0);            this.wait.Show();            try            {                if (Info.fromAddress.Trim() != string.Empty && Info.toAddress.Trim() != string.Empty)                {                    string[] separator = Info.toAddress.Split(',');                    foreach (string mailNhan in separator)                    {                        MailMessage mailMessage = this.CreateEmail(mailNhan.ToString().Trim());                        this.Smtp.Send(mailMessage);                        this.CreateTableEmail(mailMessage);                    }                    this.wait.Set(300.0);                    this.insert_Email();                }                this.wait.Set(600.0);                int num = (int)ExMessageBox.Show(1900, StartupBase.SasObj, "Gửi Email thành công.", "Thông báo", MessageBoxButton.OK, MessageBoxImage.Asterisk);                this.wait.Close();                this.Close();            }            catch (Exception ex)            {                this.wait.Close();                int num = (int)MessageBox.Show("Could not send email\n\n" + ex.ToString());            }        }        private MailMessage CreateEmail(string mailNhan)        {            if (string.IsNullOrEmpty(Info.fromName))                Info.fromName = Info.fromAddress;            MailAddress from = new MailAddress(Info.fromAddress, Info.fromName, Encoding.UTF8);            MailAddress to = new MailAddress(mailNhan);            MailMessage newmsg = new MailMessage(from, to);            newmsg.IsBodyHtml = true;            newmsg.From = from;                       newmsg.SubjectEncoding = Encoding.UTF8;            newmsg.Subject = Info.subject;            newmsg.ReplyTo = new MailAddress(Info.fromAddress, this.txttieu_de.Text);            newmsg.BodyEncoding = Encoding.UTF8;            newmsg.Body = get_mess();            if (this.lbFiles.Items != null && this.lbFiles.Items.Count > 0)            {                int count = this.lbFiles.Items.Count;                for (int i = 0; i < count; i++)                {                    string file = this.lbFiles.Items[i].ToString().Trim();                    Attachment data = new Attachment(file, MediaTypeNames.Application.Octet);                    // Add time stamp information for the file.                    System.Net.Mime.ContentDisposition disposition = data.ContentDisposition;                    disposition.CreationDate = System.IO.File.GetCreationTime(file);                    disposition.ModificationDate = System.IO.File.GetLastWriteTime(file);                    disposition.ReadDate = System.IO.File.GetLastAccessTime(file);                    newmsg.Attachments.Add(data);                }            }            return newmsg;        }        private string get_mess()        {            return this.strHtml.ToString().Trim();        }        private void insert_Email()        {            if (this.dtPH != null && this.dtPH.Rows.Count > 0)            {                SqlConnection connection = null;                this.wait.Set(350.0);                foreach (DataRow row in this.dtPH.Rows)                {                    string sql = "Insert CRMailMessagePH (messageid,email_from,tieu_de,noi_dung,noi_dung_html,ma_kh_list,email_to_list,machinename,machineuser,user_name,user_id,datesent,timesent,ma_emailcr) values (@messageid,@email_from,@tieu_de,@noi_dung,@noi_dung_html,@ma_kh_list,@email_to_list,@machinename,@machineuser,@user_name,@user_id,@datesent,@timesent,@ma_emailcr)";                    SqlCommand sqlcmd = new SqlCommand(sql, connection);                    sqlcmd.Parameters.Add("@messageid", SqlDbType.VarChar).Value = row["messageid"].ToString();                    sqlcmd.Parameters.Add("@email_from", SqlDbType.NVarChar).Value = row["email_from"].ToString();                    sqlcmd.Parameters.Add("@tieu_de", SqlDbType.NVarChar).Value = row["tieu_de"].ToString();                    sqlcmd.Parameters.Add("@noi_dung", SqlDbType.Image).Value = CrmCore.ClsLib.StrToByteArray(row["noi_dung"].ToString().Trim());                    sqlcmd.Parameters.Add("@noi_dung_html", SqlDbType.Image).Value = CrmCore.ClsLib.StrToByteArray(row["noi_dung_html"].ToString().Trim());                    sqlcmd.Parameters.Add("@ma_kh_list", SqlDbType.VarChar).Value = row["ma_kh_list"].ToString();                    sqlcmd.Parameters.Add("@email_to_list", SqlDbType.VarChar).Value = row["email_to_list"].ToString();                    sqlcmd.Parameters.Add("@machinename", SqlDbType.VarChar).Value = row["machinename"].ToString();                    sqlcmd.Parameters.Add("@machineuser", SqlDbType.VarChar).Value = row["machineuser"].ToString();                    sqlcmd.Parameters.Add("@user_name", SqlDbType.VarChar).Value = row["user_name"].ToString();                    sqlcmd.Parameters.Add("@user_id", SqlDbType.Int).Value = Convert.ToInt32(row["user_id"].ToString());                    sqlcmd.Parameters.Add("@datesent", SqlDbType.DateTime).Value = Convert.ToDateTime(row["datesent"].ToString());                    sqlcmd.Parameters.Add("@timesent", SqlDbType.VarChar).Value = row["timesent"].ToString();                    sqlcmd.Parameters.Add("@ma_emailcr", SqlDbType.VarChar).Value = StartUp.currSqlTableKey.ToString();                    int i = StartupBase.SasObj.ExcuteNonQuery(sqlcmd);                }                if (this.dtCT != null && this.dtCT.Rows.Count > 0)                {                    foreach (DataRow row in this.dtCT.Rows)                    {                        string sql = "insert into MailMessageCT(messageid,stt,filename,file_contain) values(@messageid,@stt,@filename,@file_contain)";                        SqlCommand sqlCommand3 = new SqlCommand(sql, connection);                        sqlCommand3.Parameters.Add("@messageid", SqlDbType.VarChar).Value = row["messageid"].ToString().Trim();                        sqlCommand3.Parameters.Add("@stt", SqlDbType.Int).Value = row["stt"];                        sqlCommand3.Parameters.Add("@filename", SqlDbType.NVarChar).Value = row["filename"].ToString().Trim();                        sqlCommand3.Parameters.Add("@file_contain", SqlDbType.Image).Value = (byte[])row["file_contain"];                        int i = StartupBase.SasObj.ExcuteNonQuery(sqlCommand3);                    }                }                this.wait.Set(550.0);            }        }    }}